#!/usr/bin/python3
"""Qualify one approved legacy thread; export metadata only, without changing product state."""
import datetime,json,os,pathlib,socket,subprocess
assert os.geteuid()==0 and socket.gethostname()=='hermes-home'
root=pathlib.Path('/data/hermes/himawari')
output=root/'qualifications/2026-09-11-protected/attempt-v5/native-history-audit.json'
assert output.parent.resolve()==output.parent and output.parent.stat().st_uid==0
assert not output.exists(),'Diagnostic already exists; do not repeat'
NODE_SOURCE = 'import assert from \'node:assert/strict\';\nimport { readFile } from \'node:fs/promises\';\nimport { createRequire } from \'node:module\';\nconst root=\'/data/hermes/himawari\';\nconst runtime=root+\'/releases/2026-09-11-control-center/lib/himawari-agent\';\nconst require=createRequire(runtime+\'/package.json\');\nconst {EnvelopePayloadProtector,SystemdCredentialSecretSource}=require(\'@himawari-agent/platform-node\');\nconst Database=require(\'better-sqlite3\');\nconst config=JSON.parse(await readFile(root+\'/config/production.json\',\'utf8\'));\nassert.equal(config.stateRoot,root+\'/state\');\nconst key=config.secretReferences.filter(x=>x.purpose===\'payload-encryption\');\nassert.equal(key.length,1);\nconst protector=new EnvelopePayloadProtector({keys:new SystemdCredentialSecretSource(root+\'/state/secrets\'),activeKey:{keyRef:key[0].ref,kekVersion:key[0].version,dekVersion:\'dek-v1\'}});\nconst db=new Database(root+\'/state/data/product.sqlite\',{readonly:true,fileMustExist:true});\ndb.pragma(\'query_only = ON\');\nasync function payload(ref){\n const row=db.prepare("SELECT * FROM payloads WHERE ref=? AND owner_id=? AND agent_id=? AND lifecycle_state=\'active\'").get(ref,config.ownerId,config.agentId);\n assert(row,\'PAYLOAD_MISSING\');assert.equal(row.storage_kind,\'sqlite_blob\');\n const bytes=await protector.unprotect({ownerId:row.owner_id,agentId:row.agent_id,payload:{ref:row.ref,dataClassification:row.classification,contentType:row.content_type,ciphertext:row.ciphertext,encryption:JSON.parse(row.encryption_metadata_json),contentDigest:row.content_digest,createdAt:row.created_at,storage:{kind:\'inline\'}}});\n const text=new TextDecoder().decode(bytes);\n return row.content_type===\'application/json\'?JSON.parse(text):text;\n}\n\nconst threadId=\'thread:67f83b5e-f5ab-4313-9efd-94f30e4d97b3\';\nconst runs=db.prepare(`SELECT runs.id, runs.status, MIN(m.sequence) AS sequence FROM runs JOIN thread_messages m ON m.run_id=runs.id AND m.owner_id=runs.owner_id AND m.agent_id=runs.agent_id WHERE runs.owner_id=? AND runs.agent_id=? AND runs.thread_id=? AND m.role=\'owner\' GROUP BY runs.id ORDER BY sequence LIMIT 51`).all(config.ownerId,config.agentId,threadId);\nassert(runs.length>0 && runs.length<=50,\'AUDIT_RUN_BOUND\');\nconst reports=[];\nfor(const run of runs){\n const events=db.prepare("SELECT sequence,event_type,payload_ref FROM trace_events WHERE owner_id=? AND agent_id=? AND run_id=? AND event_type=\'runtime.message\' ORDER BY sequence LIMIT 2001").all(config.ownerId,config.agentId,run.id);\n assert(events.length<=2000,\'AUDIT_EVENT_BOUND\');\n const messages=[],calls=new Set(),results=new Set(); let partial=0;\n for(const event of events){\n  const envelope=await payload(event.payload_ref); assert.equal(envelope.runId,run.id,\'AUDIT_EVENT_SCOPE\');\n  if(envelope.phase!==\'ended\'){partial++;continue;}\n  const artifact=db.prepare("SELECT content_digest FROM run_payload_artifacts WHERE owner_id=? AND agent_id=? AND run_id=? AND purpose=\'trace\' AND payload_ref=?").get(config.ownerId,config.agentId,run.id,envelope.payloadRef);\n  assert(artifact,\'AUDIT_MESSAGE_SCOPE\');\n  const message=await payload(envelope.payloadRef);\n  assert.equal(message.role,envelope.role,\'AUDIT_MESSAGE_ROLE\');\n  const content=JSON.stringify(message);\n  const nativeCalls=Array.isArray(message.content)?message.content.filter(x=>x.type===\'toolCall\'):[];\n  for(const call of nativeCalls)calls.add(call.id);\n  if(message.role===\'toolResult\')results.add(message.toolCallId);\n  messages.push({traceSequence:event.sequence,payloadRef:envelope.payloadRef,digest:artifact.content_digest,role:message.role,stopReason:message.stopReason??null,redacted:content.includes(\'[REDACTED\'),localUnwind:content.includes(\'RUNTIME_TOOL_SUSPENDED\'),toolCalls:nativeCalls.length,hasProviderIdentity:[\'provider\',\'api\',\'model\'].every(k=>typeof message[k]===\'string\')});\n }\n reports.push({runId:run.id,status:run.status,sequence:run.sequence,partialEvents:partial,finalMessages:messages,unpairedCallCount:[...calls].filter(x=>!results.has(x)).length,orphanResultCount:[...results].filter(x=>!calls.has(x)).length});\n}\ndb.close();\nconsole.log(JSON.stringify({at:new Date().toISOString(),threadId,scope:\'read-only legacy history qualification; no content, signatures, keys or provider calls\',runs:reports}));\n'
command=['/usr/bin/systemd-run','--quiet','--wait','--pipe','--collect',
 '--property=User=himawari','--property=Group=himawari',
 '--property=RuntimeMaxSec=120','--property=WorkingDirectory=/',
 '--property=NoNewPrivileges=yes','--property=PrivateNetwork=yes',
 '--property=ProtectSystem=strict','--property=PrivateTmp=yes',
 '--property=TemporaryFileSystem=/data/hermes:ro,mode=0755',
 '--property=BindReadOnlyPaths=/data/hermes/himawari',
 str(root/'releases/2026-09-11-control-center/lib/himawari-agent/pi-tools/bin/node'),'--input-type=module']
result=subprocess.run(command,input=NODE_SOURCE,text=True,capture_output=True,timeout=150)
if result.returncode:
 # Do not echo arbitrary process output that could contain private data.
 report={'passed':False,'exitCode':result.returncode,'errorLines':[line[:240] for line in result.stderr.splitlines() if line.startswith(('Error:','AssertionError','  code:'))][:4]}
else:
 report=json.loads(result.stdout)
 report['passed']=True
 assert 0 < len(report['runs']) <= 50
with output.open('x') as handle:json.dump(report,handle,ensure_ascii=False,indent=2)
output.chmod(0o644)
print('Native history audit written: '+str(output))
